CREATE DATABASE IF NOT EXISTS smartstay CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smartstay;
SET FOREIGN_KEY_CHECKS=0; DROP TABLE IF EXISTS rental_agreements,payments,bookings,rooms,properties,user_preferences,users; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(30),password VARCHAR(255) NOT NULL,role ENUM('tenant','owner','admin') DEFAULT 'tenant',status ENUM('active','suspended') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE user_preferences(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,max_budget DECIMAL(10,2) DEFAULT 0,preferred_city VARCHAR(100),food_preference VARCHAR(50),smoking VARCHAR(30),pets VARCHAR(30),sleep_schedule VARCHAR(50),cleanliness INT DEFAULT 4,social_level VARCHAR(50),room_type VARCHAR(50),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE properties(id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,title VARCHAR(180) NOT NULL,address VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,description TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE rooms(id INT AUTO_INCREMENT PRIMARY KEY,property_id INT NOT NULL,room_number VARCHAR(30) NOT NULL,room_type ENUM('private','shared') DEFAULT 'private',rent DECIMAL(10,2) NOT NULL,deposit DECIMAL(10,2) DEFAULT 0,status ENUM('available','occupied','maintenance') DEFAULT 'available',FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE bookings(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,room_id INT NOT NULL,move_in_date DATE NOT NULL,months INT DEFAULT 1,total_rent DECIMAL(10,2) NOT NULL,advance_amount DECIMAL(10,2) NOT NULL,status ENUM('pending_payment','confirmed','cancelled','completed') DEFAULT 'pending_payment',payment_status ENUM('unpaid','paid','refunded') DEFAULT 'unpaid',payment_transaction_id VARCHAR(80),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,user_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,method VARCHAR(40),transaction_id VARCHAR(80) UNIQUE,status ENUM('success','failed','refunded') DEFAULT 'success',paid_at DATETIME,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE rental_agreements(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT UNIQUE NOT NULL,agreement_no VARCHAR(80) UNIQUE NOT NULL,payment_transaction_id VARCHAR(80) NOT NULL,generated_at DATETIME NOT NULL,status ENUM('active','cancelled') DEFAULT 'active',FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
